	@Test
	void assignsTheLowestIriIdToTheMostFrequentPredicate() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		String popularPredicate = null;
		List<String> rarePredicates = new ArrayList<>();
		for (int index = 0; popularPredicate == null || rarePredicates.size() < 70; index++) {
			String candidate = "urn:ranked:predicate:" + index;
			int partition = (int) CanonicalTermCodec
					.routeHash64(CanonicalTermCodec.encode(valueFactory.createIRI(candidate))) & 3;
			if (partition == 3 && popularPredicate == null) {
				popularPredicate = candidate;
			} else {
				rarePredicates.add(candidate);
			}
		}

		StringBuilder input = new StringBuilder();
		for (int occurrence = 0; occurrence < 100; occurrence++) {
			input.append("<urn:ranked:popular-subject> <")
					.append(popularPredicate)
					.append("> <urn:ranked:popular-object> .\n");
		}
		for (int index = 0; index < rarePredicates.size(); index++) {
			input.append("<urn:ranked:subject:")
					.append(index)
					.append("> <")
					.append(rarePredicates.get(index))
					.append("> <urn:ranked:object:")
					.append(index)
					.append("> .\n");
		}

		Path target = temporaryDirectory.resolve("predicate-ranking-store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc");
		load(target, config, input.toString());

		long id = readValueIds(target, config).get(popularPredicate);
		assertThat(ValueIds.getIdType(id)).isEqualTo(ValueIds.T_URI);
		assertThat(ValueIds.getValue(id)).isEqualTo(1L);
	}

	@Test
	void plansPredicateIdsFromCountsCapturedWhileStaging() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		var popularPredicate = valueFactory.createIRI("urn:staged-count:popular");
		var rarePredicate = valueFactory.createIRI("urn:staged-count:rare");
		var quotedStatement = valueFactory.createTripleTerm(valueFactory.createIRI("urn:staged-count:quoted-subject"),
				popularPredicate, valueFactory.createIRI("urn:staged-count:quoted-object"));
		Path staging = Files.createDirectory(temporaryDirectory.resolve("predicate-count-staging"));
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(staging,
				new LmdbStoreConfig("spoc,psoc"), 4, 4, 64 * 1024L, BulkCompression.FASTEST)) {
			stager.writeStatement(valueFactory.createStatement(valueFactory.createIRI("urn:staged-count:subject"),
					popularPredicate, valueFactory.createIRI("urn:staged-count:object")));
			stager.writeCanonicalStatement(CanonicalTermCodec.encode(valueFactory.createIRI("urn:staged-count:second")),
					CanonicalTermCodec.encode(rarePredicate), CanonicalTermCodec.encode(quotedStatement), null);
			staged = stager.stagedInput();
		}
		Files.move(staging.resolve("statements.lz4"), staging.resolve("statements.saved.lz4"));

		PredicateIdPlan plan = PredicateIdPlan.build(staged, staging, () -> false);

		assertThat(ValueIds.getValue(plan.idFor(CanonicalTermCodec.encode(popularPredicate)))).isEqualTo(1L);
		assertThat(ValueIds.getValue(plan.idFor(CanonicalTermCodec.encode(rarePredicate)))).isEqualTo(2L);
	}

	@Test
	void reportsPhaseProgressAndCurrentThroughput() throws Exception {
		String input = "<urn:progress:s> <urn:progress:p> <urn:progress:o> .\n".repeat(2_050);
		Path target = temporaryDirectory.resolve("progress-store");
		List<ProgressSnapshot> snapshots = Collections.synchronizedList(new ArrayList<>());

		LmdbBulkLoader.Result result = LmdbBulkLoader
				.builder(target, new LmdbStoreConfig("spoc,psoc"))
				.partitionCount(4)
				.workers(2)
				.queueBatches(2)
				.progressListener(snapshots::add)
				.build()
				.load(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)), "urn:progress:",
						RDFFormat.NQUADS);

		assertThat(result.parsedStatements()).isEqualTo(2_050);
		assertThat(snapshots)
				.extracting(ProgressSnapshot::phase)
				.contains(BulkLoadPhase.STAGE_INPUTS, BulkLoadPhase.PUBLISH_AND_CLEAN);
		assertThat(snapshots)
				.extracting(ProgressSnapshot::phase)
				.doesNotContain(BulkLoadPhase.VALIDATE_GENERATION);
		assertThat(snapshots)
				.anyMatch(snapshot -> snapshot.phase() == BulkLoadPhase.STAGE_INPUTS
						&& snapshot.currentOperationsPerSecond() > 0.0);
		assertThat(snapshots)
				.filteredOn(snapshot -> snapshot.phaseOperations() > 0L)
				.allMatch(snapshot -> snapshot.currentOperationsPerSecond() > 0.0);
		assertThat(snapshots)
				.allMatch(snapshot -> snapshot.workers() == 2 && snapshot.queueBatches() == 2);
		assertThat(snapshots)
				.anyMatch(snapshot -> snapshot.phase() == BulkLoadPhase.PUBLISH_AND_CLEAN
						&& snapshot.phaseComplete());
	}

	@Test
	void keepsIdsAndStatementsStableAcrossForcedSpillsAndMergeFanIn() throws Exception {
		List<String> statements = new ArrayList<>();
		for (int index = 0; index < 2_000; index++) {
			statements.add("<urn:subject:" + index + "> <urn:predicate:" + index % 67 + "> \""
					+ "long-literal-" + index + "-" + "x".repeat(180) + "\" <urn:graph:" + index % 11 + "> .\n");
		}
		String forward = String.join("", statements);
		java.util.Collections.reverse(statements);
		String reverse = String.join("", statements);
		Path constrainedTarget = temporaryDirectory.resolve("constrained-spill-store");
		Path roomyTarget = temporaryDirectory.resolve("roomy-spill-store");
		Path spillParent = Files.createDirectory(temporaryDirectory.resolve("spill-workspaces"));
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc")
				.setValueDBSize(512 * 1024)
				.setTripleDBSize(512 * 1024);

		LmdbBulkLoader.Result constrained = LmdbBulkLoader.builder(constrainedTarget, config)
				.partitionCount(4)
				.memoryBudgetBytes(16 * 1024)
				.maxOpenFiles(3)
				.temporaryDirectory(spillParent)
				.build()
				.load(new ByteArrayInputStream(forward.getBytes(StandardCharsets.UTF_8)), "urn:spill:",
						RDFFormat.NQUADS);
		LmdbBulkLoader.Result roomy = LmdbBulkLoader.builder(roomyTarget, config)
				.partitionCount(4)
				.memoryBudgetBytes(1024 * 1024)
				.maxOpenFiles(32)
				.temporaryDirectory(spillParent)
				.build()
				.load(new ByteArrayInputStream(reverse.getBytes(StandardCharsets.UTF_8)), "urn:spill:",
						RDFFormat.NQUADS);

		assertThat(constrained.storedStatements()).isEqualTo(2_000);
		assertThat(roomy.storedStatements()).isEqualTo(2_000);
		assertThat(constrained.mapGrowthCount()).isPositive();
		assertThat(roomy.mapGrowthCount()).isPositive();
		assertThat(readValueIds(constrainedTarget, config)).isEqualTo(readValueIds(roomyTarget, config));
		assertThat(Models.isomorphic(readStatements(constrainedTarget), readStatements(roomyTarget))).isTrue();
		try (var children = Files.list(spillParent)) {
			assertThat(children).isEmpty();
		}
	}

